import Foundation

/// Decides which copies are worth keeping. Pure rules, so the pasteboard reading stays thin.
public enum ClipboardPolicy {
    /// Pasteboard types that password managers and other apps attach to secrets. A copy that
    /// carries any of them is never recorded.
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType"
    ]

    /// Longest text recorded, in UTF-8 bytes. Longer copies are skipped, not truncated.
    public static let maxTextBytes = 100 * 1024

    public static func isConcealed(types: [String]) -> Bool {
        types.contains { concealedTypes.contains($0) }
    }

    /// The text as it should be recorded, or `nil` for empty, whitespace-only or oversized text.
    public static func recordableText(_ text: String) -> String? {
        guard text.utf8.count <= maxTextBytes, !text.allSatisfy(\.isWhitespace) else { return nil }
        return text
    }
}
